## Part 2: Designing the Task Class

### Basic Class Structure

```python
import uuid
from datetime import datetime

class Task:
    """Represents a single task in our management system."""

    PRIORITIES = {1: "Low", 2: "Medium", 3: "High", 4: "Critical"}

    def __init__(self, title, description="", priority=2, due_date=None):
        self.id = str(uuid.uuid4())
        self.title = title
        self.description = description
        self.priority = priority
        self.due_date = due_date
        self.created_at = datetime.now()
        self.completed_at = None
        self.tags = []

    def is_complete(self):
        return self.completed_at is not None

    def add_tag(self, tag):
        if tag not in self.tags:
            self.tags.append(tag)

    def __repr__(self):
        status = "✓" if self.is_complete() else "○"
        return f"[{status}] {self.title} (Priority: {self.priority})"
```

### Adding Validation

Let's enhance our class with proper validation:

```python
class Task:
    PRIORITIES = {1: "Low", 2: "Medium", 3: "High", 4: "Critical"}

    def __init__(self, title, description="", priority=2, due_date=None):
        if not title or not title.strip():
            raise ValueError("Task title cannot be empty")

        if priority not in self.PRIORITIES:
            raise ValueError(f"Priority must be 1-4, got {priority}")

        self.id = str(uuid.uuid4())
        self.title = title.strip()
        self.description = description
        self.priority = priority
        self.due_date = due_date
        self.mark_created()

    def mark_created(self):
        self.created_at = datetime.now()
        self.completed_at = None

    def complete(self):
        if self.is_complete():
            raise RuntimeError("Task is already complete")
        self.completed_at = datetime.now()

    def reopen(self):
        if not self.is_complete():
            raise RuntimeError("Cannot reopen an incomplete task")
        self.completed_at = None

    def is_complete(self):
        return self.completed_at is not None

    def is_overdue(self):
        if self.due_date is None or self.is_complete():
            return False
        return datetime.now() > self.due_date

    def days_until_due(self):
        if self.due_date is None:
            return None
        delta = self.due_date - datetime.now()
        return delta.days

    def add_tag(self, tag):
        normalized = tag.strip().lower()
        if normalized and normalized not in self.tags:
            self.tags.append(normalized)

    def remove_tag(self, tag):
        normalized = tag.strip().lower()
        if normalized in self.tags:
            self.tags.remove(normalized)

    def __repr__(self):
        status = "✓" if self.is_complete() else "○"
        overdue = " ⚠ OVERDUE" if self.is_overdue() else ""
        return f"[{status}] {self.title}{overdue}"
```

